// Domestic fundamentals are an independently dated, reviewed publication snapshot.
// They must not be relabelled with the daily futures quote date.
function domesticProfile(m){return DOMESTIC_RESEARCH.profiles[m.code]}
function domesticFacts(ids){return (ids||[]).map(id=>DOMESTIC_RESEARCH.facts[id]).filter(Boolean)}
function domesticLatest(ids){return domesticFacts(ids).map(f=>DOMESTIC_RESEARCH.sources[f.source].published).filter(Boolean).sort().at(-1)||null}
function domesticSourceLink(id){const s=DOMESTIC_RESEARCH.sources[id];return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`}
function domesticFactCards(ids){return domesticFacts(ids).map(f=>{const s=DOMESTIC_RESEARCH.sources[f.source];return `<article class="fundamental-fact"><span class="badge">${esc(f.kind||'官方统计')}</span><h4>${esc(f.label)}</h4><strong>${esc(f.value)}</strong><p>${esc(f.note||'')}</p><small>统计期：${esc(f.period)} · 发布：${s.published||'日期未核实'}</small><div>${domesticSourceLink(f.source)}</div></article>`}).join('')}
function domesticSourceFoot(ids){const keys=[...new Set(domesticFacts(ids).map(f=>f.source))];return `<div class="dimension-provenance">本次资料核对：${DOMESTIC_RESEARCH.reviewedAt}。基础资料为人工核对的发布快照，尚未自动抓取下一期。${keys.map(k=>`<div>${domesticSourceLink(k)} · 发布 ${DOMESTIC_RESEARCH.sources[k].published||'日期未核实'}</div>`).join('')}</div>`}
function domesticPeriodNotice(ids){const latest=domesticLatest(ids);return `<p class="research-date-notice">研究资料与行情分别计时：盘面 ${DATA.asOf}；资料最近发布 ${latest||'未核实'}。${latest&&latest>DATA.asOf?'部分资料晚于盘面快照，仅作后续研究，不参与历史因子计算。':''}</p>`}
function domesticChain(m){const p=domesticProfile(m);return `<div class="domestic-chain"><article><span>01 / 国内供应</span><p>${esc(p.supply)}</p></article><article><span>02 / 国内需求</span><p>${esc(p.demand)}</p></article><article><span>03 / 供需矛盾 · 研究推断</span><p>${esc(p.inference)}</p></article><article><span>04 / 海外补充</span><p>${esc(p.overseas)}</p></article></div>`}
function domesticSupplyArticle(m){const p=domesticProfile(m),ids=[...new Set([...p.supplyFacts,...p.demandFacts])];return `<article class="dimension-article"><div class="eyebrow">DOMESTIC FUNDAMENTALS / ${esc(p.level)}</div><h3>${esc(m.name)} · 国内供需</h3><p class="dimension-summary">${esc(p.summary)}</p>${domesticPeriodNotice(ids)}${domesticChain(m)}<h4>国内供应 · 已有资料</h4><div class="fundamental-facts">${domesticFactCards(p.supplyFacts)||'<p class="research-missing">尚未取得本品种可核对的国内产量、进口或开工数据。</p>'}</div><h4>国内需求 · 已有资料</h4><div class="fundamental-facts">${domesticFactCards(p.demandFacts)||'<p class="research-missing">尚未取得本品种可核对的消费或订单数据。</p>'}</div><div class="research-gap"><strong>仍需验证</strong><p>${esc(p.missing)}</p><p>终端产量、行业总量及年度预测均按各自口径使用，不能等同于该品种当周实际消费，也不能据此判定供需缺口。</p></div><h4>补充资料入口</h4><p>${p.links.map(domesticSourceLink).join(' · ')}</p>${domesticSourceFoot(ids)}${m.code==='cu'?'<details class="legacy-research"><summary>海外历史参考 · 用户提供的LME铜截图</summary>'+legacyDimensionArticle(m,1)+'</details>':''}</article>`}
// Each commodity selects its own mechanisms and corroborating facts, never a sector fallback.
function domesticMacroIds(m){return domesticProfile(m)?.macroResearch?.facts||[]}
function domesticMacroArticle(m){
 const r=domesticProfile(m)?.macroResearch,ids=domesticMacroIds(m);
 if(!r)return `<article class="dimension-article"><h3>${esc(m.name)} · 宏观研究待配置</h3><p>尚未建立该品种的传导路径。</p></article>`;
 return `<article class="dimension-article"><div class="eyebrow">COMMODITY MACRO / 品种专属传导</div><h3>${esc(m.name)} · ${esc(r.title)}</h3><p class="dimension-summary">${esc(r.paths[0].chain)}</p><p class="research-date-notice">以下为条件式研究框架，核对日期 ${DOMESTIC_RESEARCH.reviewedAt}。尚未接入实时利率、汇率与政策事件，不构成当日涨跌归因。</p><h4>传导路径 · 需逐环验证</h4><div class="domestic-chain">${r.paths.map((p,i)=>`<article><span>0${i+1} / ${esc(p.label)}</span><p>${esc(p.chain)}</p></article>`).join('')}</div><div class="research-gap"><strong>什么情况下传导会减弱或失效</strong><p>${esc(r.counter)}</p></div><h4>本品种优先观察的变量</h4><div class="fundamental-facts">${r.watch.map(v=>`<article class="fundamental-fact"><span class="badge">跟踪变量 · 非实时读数</span><h4>${esc(v)}</h4></article>`).join('')}</div><h4>已有国内资料 · 验证线索</h4><p>下面是按本品种选择的统计或行业资料，各自保留统计期和发布日。它们只能验证传导中的部分环节，不能证明当前宏观事件已经传导到价格。</p>${domesticPeriodNotice(ids)}<div class="fundamental-facts">${domesticFactCards(ids)}</div>${domesticSourceFoot(ids)}${m.code==='cu'?'<details class="legacy-research"><summary>海外历史参考 · 用户提供的LME铜截图</summary>'+legacyDimensionArticle(m,0)+'</details>':''}</article>`;
}
function domesticInventoryArticle(m){const p=domesticProfile(m),ids=p.inventoryFacts||[];return `<article class="dimension-article"><div class="eyebrow">DOMESTIC INVENTORY / ${ids.length?'报告线索':'待取得实物库存'}</div><h3>${esc(m.name)} · 国内库存</h3>${ids.length?domesticPeriodNotice(ids):''}<div class="fundamental-facts">${domesticFactCards(ids)}</div><h4>应跟踪的库存口径</h4><p>${esc(p.inventory)}</p><div class="research-gap"><strong>${ids.length?'高频数量待补充':'暂无已核对的国内库存数量'}</strong><p>暂未接入本品种连续的交易所仓单、社会库存或厂库数量，不能给出当周累库、去库或历史分位判断。期货持仓量不是实物库存。</p></div><h4>数据来源入口</h4><p>${[p.exchangeSource,...p.links.filter(k=>['smm','cisa'].includes(k))].map(domesticSourceLink).join(' · ')}</p>${ids.length?domesticSourceFoot(ids):''}${m.code==='cu'?'<details class="legacy-research"><summary>海外历史参考 · 用户提供的LME铜库存截图</summary>'+legacyDimensionArticle(m,2)+'</details>':''}</article>`}
// Parse delivery months relative to the quote date; CZCE uses one year digit.
function domesticDelivery(contract,asOf){
 const suffix=String(contract).match(/(\d{3,4})$/)?.[1];if(!suffix)return null;
 const month=Number(suffix.slice(-2));if(month<1||month>12)return null;
 const base=Number(asOf.slice(0,4)),year=suffix.length===4?2000+Number(suffix.slice(0,2)):[base-1,base,base+1,base+2,base+3].find(y=>y%10===Number(suffix[0]));
 return year?year*12+month-1:null;
}
function domesticCurveRows(m,asOf){
 const seen=new Set(),base=Number(asOf.slice(0,4))*12+Number(asOf.slice(5,7))-1;
 return (m.contracts||[]).flatMap(c=>{const month=domesticDelivery(c.contract,asOf);if(c.code!==m.code||!new RegExp('^'+m.code+'[0-9]{3,4}$','i').test(c.contract)||c.date!==asOf||!Number.isFinite(c.settle)||c.settle<=0||!Number.isFinite(c.volume)||c.volume<=0||!Number.isFinite(c.oi)||c.oi<0||month===null||month<base||seen.has(month))return [];seen.add(month);return [{...c,month}] }).sort((a,b)=>a.month-b.month);
}
function domesticCurveSvg(rows,m){
 if(rows.length<2)return '';
 const W=720,H=260,p={l:65,r:25,t:28,b:60},values=rows.map(r=>r.settle),lo=Math.min(...values),hi=Math.max(...values),pad=(hi-lo||Math.max(1,hi*.01))*.15,min=lo-pad,max=hi+pad;
 const x=r=>p.l+(r.month-rows[0].month)/(rows.at(-1).month-rows[0].month)*(W-p.l-p.r),y=v=>p.t+(max-v)/(max-min)*(H-p.t-p.b);
 const ticks=Array.from({length:4},(_,i)=>min+(max-min)*i/3),step=Math.max(1,Math.ceil(rows.length/8));
 return `<svg class="domestic-curve" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(m.name)} ${DATA.asOf} 同日结算价期限曲线，横轴交割月份，纵轴${esc(m.unit)}"><title>${esc(m.name)} 同日结算价 / ${DATA.asOf}</title>${ticks.map(v=>`<line x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}"/><text x="${p.l-8}" y="${y(v)+4}" text-anchor="end">${num(v,decimals(m))}</text>`).join('')}<polyline points="${rows.map(r=>`${x(r)},${y(r.settle)}`).join(' ')}"/>${rows.map((r,i)=>`<circle cx="${x(r)}" cy="${y(r.settle)}" r="4"><title>${esc(r.contract.toUpperCase())}：${num(r.settle,2)} ${esc(m.unit)}</title></circle>${i%step===0||i===rows.length-1?`<text x="${x(r)}" y="${H-p.b+22}" text-anchor="middle">${esc(r.contract.toUpperCase())}</text>`:''}`).join('')}<text x="${p.l}" y="15">结算价 / ${esc(m.unit)}</text><text x="${W/2}" y="${H-8}" text-anchor="middle">交割月份（按实际月份间隔）</text></svg>`;
}
function domesticCurveArticle(m){const rows=domesticCurveRows(m,DATA.asOf),first=rows[0],far=rows[1];return `<article class="dimension-article"><div class="eyebrow">DOMESTIC TERM STRUCTURE / ${DATA.asOf} 收盘快照</div><h3>${esc(m.name)} · 国内合约结构</h3>${rows.length>=2?`<p class="dimension-summary">最近两个有成交合约 ${esc(first.contract.toUpperCase())} − ${esc(far.contract.toUpperCase())} = ${signed(first.settle-far.settle,2)} ${esc(m.unit)}。</p><p>${first.settle>far.settle?'近端结算价高于下一交割月；仅描述这两个合约。':first.settle<far.settle?'近端结算价低于下一交割月；仅描述这两个合约。':'最近两个交割月结算价持平。'}不将局部月差推为整条曲线的形态。</p>${domesticCurveSvg(rows,m)}<div class="table-wrap"><table class="market-table"><thead><tr><th>合约</th><th>结算价 / ${esc(m.unit)}</th><th>最近合约 − 本合约</th><th>成交量 / 手</th><th>持仓量 / 手</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.contract.toUpperCase())}</td><td>${num(r.settle,2)}</td><td>${signed(first.settle-r.settle,2)}</td><td>${num(r.volume)}</td><td>${num(r.oi)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="research-gap"><strong>有效交割月不足两个，暂不绘图</strong><p>当前快照仅保留 ${rows.length} 个同日、有效结算价且有成交的合约。需补全多交割月行情后才能计算月差。</p></div>`}<p class="dimension-provenance">来源：<a href="${esc(sourceOf(m).url)}" target="_blank" rel="noopener noreferrer">${esc(sourceOf(m).name)} ↗</a> · ${DATA.asOf}。统一使用结算价；无成交、错日、跨品种、无效月份和缺失结算价剔除。不拼接历史，不以结算价代替现货报价；暂未接入同一合约对的历史月差变化。</p>${m.code==='cu'?'<details class="legacy-research"><summary>海外历史参考 · 用户提供的LME铜期限结构截图</summary>'+legacyDimensionArticle(m,3)+'</details>':''}</article>`}
const legacyDimensionArticle=dimensionArticle;
dimensionArticle=function(m,i){if(!domesticProfile(m))return legacyDimensionArticle(m,i);return [domesticMacroArticle,domesticSupplyArticle,domesticInventoryArticle,domesticCurveArticle][i](m)};
const domesticDetailBase=researchDetail;
researchDetail=function(){const m=selected();let html=domesticDetailBase();const p=domesticProfile(m);if(!p)return html;const labels=['品种传导',p.level,p.inventoryFacts?.length?'报告线索':'待补数量',domesticCurveRows(m,DATA.asOf).length>=2?'国内曲线':'合约不足'];html=html.replace(/<small>(截图资料|待补资料)<\/small>/g,()=>`<small>${esc(labels.shift())}</small>`);html=html.replace('LME铜资料参考 · 境内沪铜盘面另见下方','国内供需为主线 · 海外截图折叠为历史参考').replace('选择维度查看资料与跟踪项目','国内资料与盘面分别标注日期 · 行业线索与品种证据分开展示');return html};
const domesticHomeBase=productResearchHome;
productResearchHome=function(){domesticHomeBase();const h=$('.product-research-home');if(!h)return;h.querySelector('.chart-note').textContent=`盘面 ${DATA.asOf}；国内研究资料核对 ${DOMESTIC_RESEARCH.reviewedAt}。供需资料为人工发布快照，合约结构随行情快照计算；相对强度仍以原始全市场样本计算。`;h.querySelectorAll('[data-product]').forEach(b=>{const p=DOMESTIC_RESEARCH.profiles[b.dataset.product];if(p)b.insertAdjacentHTML('beforeend',`<small class="product-research-state">供需 · ${esc(p.level)}</small>`)});};

